Java<pre><code>package com.app.model;

import javax.persistence.*;

@Entity
@Table(name = "user")
public class User {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "username", unique = true, nullable = false)
    private String username;

    @Column(name = "password", nullable = false)
    private String password;

    public User() {
    }
    public User(String username, String password) {
        this.username = username;
        this.password = password;
    }
    public Long getId() {return id;}
    public void setId(Long id) {this.id = id;}
    public String getUsername() {return username;}
    public void setUsername(String username) {this.username = username;}
    public String getPassword() {return password;}
    public void setPassword(String password) {this.password = password;}

    @Override
    public String toString() {
        return "User{" +
                "id=" + id +
                ", username='" + username + '\'' +
                '}';
    }
}
</code></pre>

Java<pre><code>package com.app.service.impl;

import com.app.dao.UserDao;
import com.app.model.User;
import com.app.service.UserService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional; // ​导入​事务​注解​

@Service("userService") // ​注册​为​Spring Bean
@Transactional // ​声明​事务​
public class UserServiceImpl implements UserService {

    @Autowired
    private UserDao userDao;

    @Override
    public User login(String username, String password) {
        // ​从​数据库​查询​用户​
        User user = userDao.findByUsername(username);
        if (user != null &amp;&amp; user.getPassword().equals(password)) {
            return user;
        }
        return null;
    }
}
</code></pre>

Java<pre><code>package com.app.action;

import com.app.service.UserService;
import com.opensymphony.xwork2.ActionSupport;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;

@Controller
public class LoginAction extends ActionSupport {

    private String username;
    private String password;

    @Autowired
    private UserService userService;
    public String getUsername() {return username;}
    public void setUsername(String username) {this.username = username;}
    public String getPassword() {return password;}
    public void setPassword(String password) {this.password = password;}

    @Override
    public String execute() throws Exception {
        if (username == null || username.isEmpty() || password == null || password.isEmpty()) {
            addActionError("Username and password can not be empty");
            return INPUT;
        }

        if (userService.login(username, password) != null) {
            addActionMessage("Login successfully");
            return SUCCESS;
        } else {
            addActionError("Wrong username or password");
            return INPUT;
        }
    }
}
</code></pre>

